CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(320) NOT NULL,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(120) NOT NULL,email_verified_at DATETIME NULL,status ENUM('active','suspended') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY users_email_unique(email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_sessions(id CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,KEY sessions_expiry_idx(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE workspaces(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,workspace_type ENUM('personal','company') NOT NULL,owner_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE workspace_members(workspace_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,role ENUM('owner','admin','editor','analyst','viewer') NOT NULL,status ENUM('active','removed') NOT NULL DEFAULT 'active',joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(workspace_id,user_id),FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE workspace_invitations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,email VARCHAR(320) NOT NULL,role ENUM('admin','editor','analyst','viewer') NOT NULL,token_hash CHAR(64) NOT NULL,status ENUM('pending','accepted','expired','revoked') NOT NULL DEFAULT 'pending',invited_by BIGINT UNSIGNED NOT NULL,expires_at DATETIME NOT NULL,accepted_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(invited_by) REFERENCES users(id),UNIQUE KEY invitations_token_unique(token_hash),KEY invitations_workspace_status_idx(workspace_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_user_id BIGINT UNSIGNED NULL,workspace_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,target_type VARCHAR(80) NOT NULL,target_id VARCHAR(80) NULL,metadata JSON NULL,ip_address VARCHAR(45) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY audit_workspace_created_idx(workspace_id,created_at),KEY audit_actor_created_idx(actor_user_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
